export const MOTION_TEMPLATES_API='/api/studio/motion-templates';
export const sessionStatus={draft:'准备内容',source_review:'检查素材与人物',ready_to_prepare:'可以准备画面',plan_review:'检查原生编排',preview_review:'检查排版预览',ready_to_render:'可以生成',submitted:'已提交制作',completed:'已完成'};
export function sessionPatch(value){return Object.fromEntries(['title','script','brand','short_title','presenter_label','layout','presenter_mode','content','sound'].map(k=>[k,value[k]]));}
export function canUseTemplate(template){return ['ready','testing'].includes(template?.status);}
export function needsSourceGeneration(session){return session.sound.mode!=='reuse'||!session.reuse_matches_script;}
export function generationBudget(quote,amount){const maximum=Math.round(Number(amount)*1000000);return Number.isSafeInteger(maximum)&&maximum>0&&maximum>=Number(quote?.known_max_micros||0)?maximum:null;}
export function reviewComplete(images,seen){return !!images?.length&&images.every(i=>seen.includes(i.id));}
export function inheritedSound(input){if(input?.soundMode==='voice'&&input.voiceId)return {mode:'voice',modelId:input.modelId||'haike/cosyvoice',voiceId:input.voiceId,rate:input.rate||1};if(input?.soundMode==='audio'&&input.audio)return {mode:'audio',modelId:input.modelId||'haike/cosyvoice',voiceId:'',rate:1};return null;}
export const fieldLabels={chapter:'章节标题','burden.claim':'问题说明','burden.recordingLabel':'时间线标签','lens.wideLabel':'全景标签','reflection.connector':'收尾连接词',context:'开场情境','claim.subject':'开场主语','claim.connector':'开场连接词','claim.destination':'开场重点','burden.heading':'问题标题','response.invitation':'回应开头','response.subject':'回应主题','response.connector':'结论连接词','response.conclusion':'开场结论','scope.connector':'分类引导','scope.initial':'分类对象','scope.heading':'分类重点','scope.conclusion':'分类结论','wall.attribution':'素材墙来源说明','wall.countLabel':'素材墙标注','claim.line1':'主张第一行','claim.line2':'主张第二行','claim.line3':'主张重点','contrast.line1':'划线文案第一行','contrast.line2':'划线文案第二行','template.label':'标签文字','lens.connector':'镜头引导','lens.heading':'镜头标题','lens.pushLabel':'推进标签','lens.trackLabel':'跟随标签','lens.closeLabel':'近景标签','rhythm.heading':'节奏标题','reflection.context':'收尾引导','reflection.subject':'收尾主语','reflection.era':'收尾主题','reflection.conclusion':'收尾结论','capacity.heading':'步骤标题','capacity.opponentLabel':'左侧标签','capacity.selfLabel':'右侧标签','capacity.augmentationLabel':'增强说明','capacity.factor':'步骤／示意数量（须真实）','action.heading':'行动按钮','brand.line1':'品牌第一行','brand.line2':'品牌第二行','brand.description':'门店地址或介绍','invitation.heading':'邀请标题','invitation.note':'邀请说明',signoff:'落款','reaction.label':'画格说明'};
export function contentLabel(key){const category=key.match(/^categories\.(\d)\.(label|note)$/);if(category)return `分类${Number(category[1])+1}${category[2]==='label'?'名称':'说明'}`;const part=key.match(/^rhythm.parts\.(\d)$/);return part?`节奏词${Number(part[1])+1}`:fieldLabels[key]||key;}
